import AppKit
import SwiftUI

public enum AppIconProvider {
    private static let base64Icon = ""

    private static let cachedIcon: NSImage? = {
        if let data = Data(base64Encoded: base64Icon),
           let img = NSImage(data: data) {
            return img
        }

        let candidates = [
            "Assets.xcassets/icone.png",
            "ProcessControlApp/Assets.xcassets/icone.png",
            "Assets.xcassets/icone_512.png",
            "Assets.xcassets/AppIcon.icns",
            "ProcessControlApp/Assets.xcassets/AppIcon.icns"
        ]

        let fileManager = FileManager.default
        let roots = [
            URL(fileURLWithPath: fileManager.currentDirectoryPath),
            URL(fileURLWithPath: CommandLine.arguments.first ?? "").deletingLastPathComponent(),
            Bundle.main.bundleURL,
            Bundle.main.resourceURL ?? Bundle.main.bundleURL
        ]

        for root in roots {
            var folder = root
            for _ in 0..<6 {
                for candidate in candidates {
                    let fileURL = folder.appendingPathComponent(candidate)
                    if fileManager.fileExists(atPath: fileURL.path),
                       let img = NSImage(contentsOf: fileURL) {
                        return img
                    }
                }
                folder.deleteLastPathComponent()
            }
        }
        return NSImage(named: NSImage.applicationIconName)
    }()

    public static func loadAppIcon() -> NSImage? {
        return cachedIcon
    }
}
